import json,re,bisect
from datetime import datetime
ev=[json.loads(l) for l in open('events.jsonl')]
def dt(s): return datetime.strptime(s[:19],'%Y-%m-%dT%H:%M:%S')
comp={'s1':[], 'ul':[]}
for e in ev:
    if e['k']=='compact': comp['s1' if e['src']=='s1' else 'ul'].append(e['ts'])
for k in comp: comp[k].sort()
pat=re.compile(r"boot|restore|resume|wake|container|where we|reboot|context",re.I)
for e in ev:
    if e['k']!='human' or e['src']=='rec': continue
    if not pat.search(e['text'][:400]): continue
    g='s1' if e['src']=='s1' else 'ul'
    c=comp[g]; i=bisect.bisect_right(c,e['ts'])-1
    since=(dt(e['ts'])-dt(c[i])).total_seconds()/60 if i>=0 else None
    if since is not None and since<=15: continue
    print(e['ts'][:19],g,'since=%s'%(None if since is None else int(since)),e['len'],repr(e['text'][:200]))
EOF
